 471→// createWorktree creates a git worktree using native git command
 472→func createWorktree(repoDir, worktreeDir, branch string) error {
 473→	cmd := exec.CommandContext(context.Background(), "git", "worktree", "add", worktreeDir, "-b", branch)
 474→	cmd.Dir = repoDir
 475→	return cmd.Run()
 476→}
 477→
 478→// removeWorktree removes a git worktree using native git command
 479→func removeWorktree(repoDir, worktreeDir string) {
 480→	cmd := exec.CommandContext(context.Background(), "git", "worktree", "remove", worktreeDir, "--force")
 481→	cmd.Dir = repoDir
 482→	_ = cmd.Run() //nolint:errcheck // Best effort cleanup, ignore errors
 483→}
