package strategy

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"sync"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

func TestOpenRepository(t *testing.T) {
	// Create a temporary directory for the test repository
	tmpDir := t.TempDir()

	// Initialize a git repository
	repo, err := git.PlainInit(tmpDir, false)
	if err != nil {
		t.Fatalf("failed to init repo: %v", err)
	}

	// Create a test file and commit it
	testFile := filepath.Join(tmpDir, "test.txt")
	if err := os.WriteFile(testFile, []byte("test content"), 0o644); err != nil {
		t.Fatalf("failed to write test file: %v", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}

	if _, err := worktree.Add("test.txt"); err != nil {
		t.Fatalf("failed to add file: %v", err)
	}

	if _, err := worktree.Commit("Initial commit", &git.CommitOptions{
		Author: &object.Signature{
			Name:  "Test User",
			Email: "test@example.com",
		},
	}); err != nil {
		t.Fatalf("failed to commit: %v", err)
	}

	// Change to the repository directory
	t.Chdir(tmpDir)

	// Test OpenRepository
	openedRepo, err := OpenRepository()
	if err != nil {
		t.Fatalf("OpenRepository() failed: %v", err)
	}

	if openedRepo == nil {
		t.Fatal("OpenRepository() returned nil repository")
	}

	// Verify we can perform basic operations
	head, err := openedRepo.Head()
	if err != nil {
		t.Fatalf("failed to get HEAD: %v", err)
	}

	if head == nil {
		t.Fatal("HEAD is nil")
	}

	// Verify we can get the commit
	commit, err := openedRepo.CommitObject(head.Hash())
	if err != nil {
		t.Fatalf("failed to get commit: %v", err)
	}

	if commit.Message != "Initial commit" {
		t.Errorf("expected commit message 'Initial commit', got '%s'", commit.Message)
	}
}

func TestOpenRepositoryError(t *testing.T) {
	// Create a temporary directory without git repository
	tmpDir := t.TempDir()

	// Change to the non-repository directory
	t.Chdir(tmpDir)

	// Test OpenRepository should fail
	_, err := OpenRepository()
	if err == nil {
		t.Fatal("OpenRepository() should have failed in non-repository directory")
	}
}

func TestWorktreeRoot_Cache(t *testing.T) {
	// Uses t.Chdir + t.Setenv so cannot be parallel.
	tmpDir := t.TempDir()
	initTestRepo(t, tmpDir)
	t.Chdir(tmpDir)
	paths.ClearWorktreeRootCache()

	// First call populates the cache via git.
	got, err := paths.WorktreeRoot()
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() first call error: %v", err)
	}

	// Resolve symlinks for comparison (macOS /var -> /private/var).
	want, err := filepath.EvalSymlinks(tmpDir)
	if err != nil {
		t.Fatalf("EvalSymlinks error: %v", err)
	}
	if got != want {
		t.Fatalf("paths.WorktreeRoot() = %q, want %q", got, want)
	}

	// Break git by pointing PATH at an empty directory.
	// If the second call hits git it will fail.
	emptyDir := t.TempDir()
	t.Setenv("PATH", emptyDir)

	got2, err := paths.WorktreeRoot()
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() cached call should succeed, got error: %v", err)
	}
	if got2 != want {
		t.Fatalf("paths.WorktreeRoot() cached = %q, want %q", got2, want)
	}

	// After clearing the cache the broken PATH should cause a failure.
	paths.ClearWorktreeRootCache()
	_, err = paths.WorktreeRoot()
	if err == nil {
		t.Fatal("paths.WorktreeRoot() should fail after cache clear with broken PATH")
	}
}

func TestWorktreeRoot_MainRepo(t *testing.T) {
	// In a normal (non-worktree) repo, WorktreeRoot returns the repo root.
	// Uses t.Chdir so cannot be parallel.
	tmpDir := t.TempDir()
	resolved, err := filepath.EvalSymlinks(tmpDir)
	if err != nil {
		t.Fatalf("EvalSymlinks error: %v", err)
	}
	tmpDir = resolved

	initTestRepo(t, tmpDir)
	t.Chdir(tmpDir)
	paths.ClearWorktreeRootCache()

	got, err := paths.WorktreeRoot()
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() error: %v", err)
	}
	if got != tmpDir {
		t.Errorf("paths.WorktreeRoot() = %q, want repo root %q", got, tmpDir)
	}

	// Also works from a subdirectory.
	subDir := filepath.Join(tmpDir, "sub", "dir")
	if err := os.MkdirAll(subDir, 0o755); err != nil {
		t.Fatalf("failed to create subdir: %v", err)
	}
	t.Chdir(subDir)
	paths.ClearWorktreeRootCache()

	got, err = paths.WorktreeRoot()
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() from subdir error: %v", err)
	}
	if got != tmpDir {
		t.Errorf("paths.WorktreeRoot() from subdir = %q, want repo root %q", got, tmpDir)
	}
}

func TestWorktreeRoot_Worktree(t *testing.T) {
	// In a git worktree, WorktreeRoot must return the worktree's own root,
	// NOT the main repository root. The worktree is placed in a separate
	// temp directory (sibling, not child) so the two paths share no prefix.
	// Uses t.Chdir so cannot be parallel.
	mainDir := t.TempDir()
	mainResolved, err := filepath.EvalSymlinks(mainDir)
	if err != nil {
		t.Fatalf("EvalSymlinks error: %v", err)
	}
	mainDir = mainResolved

	initTestRepo(t, mainDir)

	worktreeDir := t.TempDir()
	wtResolved, err := filepath.EvalSymlinks(worktreeDir)
	if err != nil {
		t.Fatalf("EvalSymlinks error: %v", err)
	}
	worktreeDir = wtResolved

	// t.TempDir() creates the directory; git worktree add needs it to not exist.
	if err := os.Remove(worktreeDir); err != nil {
		t.Fatalf("failed to remove temp dir for worktree: %v", err)
	}
	if err := createWorktree(mainDir, worktreeDir, "wt-branch"); err != nil {
		t.Fatalf("failed to create worktree: %v", err)
	}
	t.Cleanup(func() { removeWorktree(mainDir, worktreeDir) })

	t.Chdir(worktreeDir)
	paths.ClearWorktreeRootCache()

	got, err := paths.WorktreeRoot()
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() error: %v", err)
	}
	if got != worktreeDir {
		t.Errorf("paths.WorktreeRoot() = %q, want worktree root %q", got, worktreeDir)
	}
	if got == mainDir {
		t.Errorf("paths.WorktreeRoot() returned main repo root %q, must return worktree root", mainDir)
	}

	// Also works from a subdirectory within the worktree.
	subDir := filepath.Join(worktreeDir, "deep", "sub")
	if err := os.MkdirAll(subDir, 0o755); err != nil {
		t.Fatalf("failed to create subdir: %v", err)
	}
	t.Chdir(subDir)
	paths.ClearWorktreeRootCache()

	got, err = paths.WorktreeRoot()
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() from worktree subdir error: %v", err)
	}
	if got != worktreeDir {
		t.Errorf("paths.WorktreeRoot() from worktree subdir = %q, want %q", got, worktreeDir)
	}
	if got == mainDir {
		t.Errorf("paths.WorktreeRoot() from worktree subdir returned main repo root %q", mainDir)
	}
}

func TestIsInsideWorktree(t *testing.T) {
	t.Run("main repo", func(t *testing.T) {
		tmpDir := t.TempDir()
		initTestRepo(t, tmpDir)
		t.Chdir(tmpDir)

		if IsInsideWorktree() {
			t.Error("IsInsideWorktree() should return false in main repo")
		}
	})

	t.Run("worktree", func(t *testing.T) {
		tmpDir := t.TempDir()
		initTestRepo(t, tmpDir)

		// Create a worktree
		worktreeDir := filepath.Join(tmpDir, "worktree")
		if err := createWorktree(tmpDir, worktreeDir, "test-branch"); err != nil {
			t.Fatalf("failed to create worktree: %v", err)
		}
		t.Cleanup(func() {
			removeWorktree(tmpDir, worktreeDir)
		})

		t.Chdir(worktreeDir)

		if !IsInsideWorktree() {
			t.Error("IsInsideWorktree() should return true in worktree")
		}
	})

	t.Run("non-repo", func(t *testing.T) {
		tmpDir := t.TempDir()
		t.Chdir(tmpDir)

		if IsInsideWorktree() {
			t.Error("IsInsideWorktree() should return false in non-repo")
		}
	})
}

func TestGetMainRepoRoot(t *testing.T) {
	t.Run("main repo", func(t *testing.T) {
		tmpDir := t.TempDir()
		// Resolve symlinks (macOS /var -> /private/var)
		// git rev-parse --show-toplevel returns the resolved path
		resolved, err := filepath.EvalSymlinks(tmpDir)
		if err != nil {
			t.Fatalf("filepath.EvalSymlinks() failed: %v", err)
		}
		tmpDir = resolved

		initTestRepo(t, tmpDir)
		t.Chdir(tmpDir)

		root, err := GetMainRepoRoot()
		if err != nil {
			t.Fatalf("GetMainRepoRoot() failed: %v", err)
		}

		if root != tmpDir {
			t.Errorf("GetMainRepoRoot() = %q, want %q", root, tmpDir)
		}
	})

	t.Run("worktree", func(t *testing.T) {
		tmpDir := t.TempDir()
		// Resolve symlinks (macOS /var -> /private/var)
		resolved, err := filepath.EvalSymlinks(tmpDir)
		if err != nil {
			t.Fatalf("filepath.EvalSymlinks() failed: %v", err)
		}
		tmpDir = resolved

		initTestRepo(t, tmpDir)

		worktreeDir := filepath.Join(tmpDir, "worktree")
		if err := createWorktree(tmpDir, worktreeDir, "test-branch"); err != nil {
			t.Fatalf("failed to create worktree: %v", err)
		}
		t.Cleanup(func() {
			removeWorktree(tmpDir, worktreeDir)
		})

		t.Chdir(worktreeDir)

		root, err := GetMainRepoRoot()
		if err != nil {
			t.Fatalf("GetMainRepoRoot() failed: %v", err)
		}

		if root != tmpDir {
			t.Errorf("GetMainRepoRoot() = %q, want %q", root, tmpDir)
		}
	})
}

func TestGetCurrentBranchName(t *testing.T) {
	t.Run("on branch", func(t *testing.T) {
		tmpDir := t.TempDir()
		repo, err := git.PlainInit(tmpDir, false)
		if err != nil {
			t.Fatalf("failed to init repo: %v", err)
		}

		// Create initial commit
		testFile := filepath.Join(tmpDir, "test.txt")
		if err := os.WriteFile(testFile, []byte("test"), 0o644); err != nil {
			t.Fatalf("failed to write file: %v", err)
		}

		wt, err := repo.Worktree()
		if err != nil {
			t.Fatalf("failed to get worktree: %v", err)
		}

		if _, err := wt.Add("test.txt"); err != nil {
			t.Fatalf("failed to add file: %v", err)
		}

		if _, err := wt.Commit("Initial commit", &git.CommitOptions{
			Author: &object.Signature{Name: "Test", Email: "test@test.com"},
		}); err != nil {
			t.Fatalf("failed to commit: %v", err)
		}

		// Should be on default branch (master or main)
		branchName := GetCurrentBranchName(repo)
		if branchName == "" {
			t.Error("GetCurrentBranchName() returned empty string, expected branch name")
		}

		// Create and checkout a new branch
		head, err := repo.Head()
		if err != nil {
			t.Fatalf("failed to get HEAD: %v", err)
		}

		newBranch := "feature/test-branch"
		if err := wt.Checkout(&git.CheckoutOptions{
			Branch: plumbing.NewBranchReferenceName(newBranch),
			Create: true,
			Hash:   head.Hash(),
		}); err != nil {
			t.Fatalf("failed to checkout branch: %v", err)
		}

		// Should return the new branch name
		branchName = GetCurrentBranchName(repo)
		if branchName != newBranch {
			t.Errorf("GetCurrentBranchName() = %q, want %q", branchName, newBranch)
		}
	})

