func initBareWithMetadataBranch(t *testing.T) string {
	t.Helper()
	bareDir := t.TempDir()

	// Init bare, create main branch with a commit
	workDir := t.TempDir()
	run := func(dir string, args ...string) {
		cmd := exec.CommandContext(context.Background(), "git", args...)
		cmd.Dir = dir
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v failed: %v\n%s", args, err, out)
		}
	}
	run(bareDir, "init", "--bare")
	run(workDir, "clone", bareDir, ".")
	os.WriteFile(filepath.Join(workDir, "README.md"), []byte("# Test"), 0o644) //nolint:errcheck // test setup
	run(workDir, "add", ".")
	run(workDir, "commit", "-m", "init")
	run(workDir, "push", "origin", "main")

	// Create orphan entire/checkpoints/v1 with data
	run(workDir, "checkout", "--orphan", paths.MetadataBranchName)
	run(workDir, "rm", "-rf", ".")
	os.WriteFile(filepath.Join(workDir, "metadata.json"), []byte(`{"checkpoint_id":"test123"}`), 0o644) //nolint:errcheck
