		isDefault, branchName := IsOnDefaultBranch(repo)
		if isDefault {
			t.Error("IsOnDefaultBranch() = true, want false for detached HEAD")
		}
		if branchName != "" {
			t.Errorf("branchName = %q, want empty string for detached HEAD", branchName)
		}
	})
}

