288→// EnsureMetadataBranch creates or updates the local entire/checkpoints/v1 branch.
289→// If the remote-tracking branch (origin/entire/checkpoints/v1) exists and the local
290→// branch is missing or empty, creates/updates the local branch from it.
291→// Otherwise creates an empty orphan.
292→func EnsureMetadataBranch(repo *git.Repository) error {
293→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
294→
295→	// Check if remote-tracking branch exists (e.g., after clone/fetch)
296→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
297→	remoteRef, remoteErr := repo.Reference(remoteRefName, true)
298→	if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
299→		return fmt.Errorf("failed to check remote metadata branch: %w", remoteErr)
300→	}
301→
302→	// Check if local branch already exists
303→	localRef, err := repo.Reference(refName, true)
304→	if err == nil {
305→		// If local is an empty orphan and remote has data, update from remote.
306→		// This fixes repos where enable ran before the remote had checkpoint data.
307→		if remoteErr == nil && localRef.Hash() != remoteRef.Hash() {
308→			isEmpty, checkErr := isEmptyMetadataBranch(repo, localRef)
309→			if checkErr == nil && isEmpty {
310→				ref := plumbing.NewHashReference(refName, remoteRef.Hash())
311→				if setErr := repo.Storer.SetReference(ref); setErr != nil {
312→					return fmt.Errorf("failed to update metadata branch from remote: %w", setErr)
313→				}
314→				fmt.Fprintf(os.Stderr, "✓ Updated local branch '%s' from origin\n", paths.MetadataBranchName)
315→			}
316→		}
317→		return nil
318→	}
319→	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
320→		return fmt.Errorf("failed to check metadata branch: %w", err)
321→	}
322→
323→	// Local branch doesn't exist — create from remote if available
324→	if remoteErr == nil {
325→		ref := plumbing.NewHashReference(refName, remoteRef.Hash())
326→		if err := repo.Storer.SetReference(ref); err != nil {
327→			return fmt.Errorf("failed to create metadata branch from remote: %w", err)
328→		}
329→		fmt.Fprintf(os.Stderr, "✓ Created local branch '%s' from origin\n", paths.MetadataBranchName)
330→		return nil
331→	}
332→
333→	// No local or remote branch — create empty orphan
334→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
335→	obj := repo.Storer.NewEncodedObject()
336→	if err := emptyTree.Encode(obj); err != nil {
337→		return fmt.Errorf("failed to encode empty tree: %w", err)
338→	}
339→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
340→	if err != nil {
341→		return fmt.Errorf("failed to store empty tree: %w", err)
342→	}
343→
344→	// Create orphan commit (no parent)
345→	now := time.Now()
346→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
347→	sig := object.Signature{
348→		Name:  authorName,
349→		Email: authorEmail,
350→		When:  now,
351→	}
352→
353→	commit := &object.Commit{
354→		TreeHash:  emptyTreeHash,
355→		Author:    sig,
356→		Committer: sig,
357→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata.\n",
358→	}
359→	// Note: No ParentHashes - this is an orphan commit
360→
361→	commitObj := repo.Storer.NewEncodedObject()
362→	if err := commit.Encode(commitObj); err != nil {
363→		return fmt.Errorf("failed to encode orphan commit: %w", err)
364→	}
365→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
366→	if err != nil {
367→		return fmt.Errorf("failed to store orphan commit: %w", err)
368→	}
369→
370→	// Create branch reference
371→	ref := plumbing.NewHashReference(refName, commitHash)
372→	if err := repo.Storer.SetReference(ref); err != nil {
373→		return fmt.Errorf("failed to create metadata branch: %w", err)
374→	}
375→
376→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
377→	return nil
378→}
