1368→	}
1369→
1370→	hash, err := repo.Storer.SetEncodedObject(obj)
1371→	if err != nil {
1372→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1373→	}
1374→	return hash, nil
1375→}
