 39→// WriteCommitted writes a committed checkpoint to the entire/checkpoints/v1 branch.
 40→// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
 41→//
 42→// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
 43→//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
 44→//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
 45→func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
 46→	// Validate identifiers to prevent path traversal and malformed data
 47→	if opts.CheckpointID.IsEmpty() {
 48→		return errors.New("invalid checkpoint options: checkpoint ID is required")
 49→	}
 50→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
 51→		return fmt.Errorf("invalid checkpoint options: %w", err)
 52→	}
 53→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
 54→		return fmt.Errorf("invalid checkpoint options: %w", err)
 55→	}
 56→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
 57→		return fmt.Errorf("invalid checkpoint options: %w", err)
 58→	}
 59→
 60→	// Ensure sessions branch exists
 61→	if err := s.ensureSessionsBranch(); err != nil {
 62→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
 63→	}
 64→
 65→	// Get branch ref and root tree hash (O(1), no flatten)
 66→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
 67→	if err != nil {
 68→		return err
 69→	}
 70→
 71→	// Use sharded path: <id[:2]>/<id[2:]>/
 72→	basePath := opts.CheckpointID.Path() + "/"
 73→	checkpointPath := opts.CheckpointID.Path()
 74→
 75→	// Flatten only the checkpoint subtree (O(files in checkpoint))
 76→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
 77→	if err != nil {
 78→		return err
 79→	}
 80→
 81→	// Track task metadata path for commit trailer
 82→	var taskMetadataPath string
 83→
 84→	// Handle task checkpoints
 85→	if opts.IsTask && opts.ToolUseID != "" {
 86→		taskMetadataPath, err = s.writeTaskCheckpointEntries(ctx, opts, basePath, entries)
 87→		if err != nil {
 88→			return err
 89→		}
 90→	}
 91→
 92→	// Write standard checkpoint entries (transcript, prompts, context, metadata)
 93→	if err := s.writeStandardCheckpointEntries(ctx, opts, basePath, entries); err != nil {
 94→		return err
 95→	}
 96→
 97→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
 98→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
 99→	if err != nil {
100→		return err
101→	}
102→
103→	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
104→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
105→	if err != nil {
106→		return err
107→	}
108→
109→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
110→	newRef := plumbing.NewHashReference(refName, newCommitHash)
111→	if err := s.repo.Storer.SetReference(newRef); err != nil {
112→		return fmt.Errorf("failed to set branch reference: %w", err)
113→	}
114→
115→	return nil
116→}
