784→// FlattenTree recursively flattens a tree into a map of full paths to entries.
785→func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
786→	for _, entry := range tree.Entries {
787→		fullPath := entry.Name
788→		if prefix != "" {
789→			fullPath = prefix + "/" + entry.Name
790→		}
791→
792→		if entry.Mode == filemode.Dir {
793→			// Recurse into subtree
794→			subtree, err := repo.TreeObject(entry.Hash)
795→			if err != nil {
796→				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
797→			}
798→			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
799→				return err
800→			}
801→		} else {
802→			entries[fullPath] = object.TreeEntry{
803→				Name: fullPath,
804→				Mode: entry.Mode,
805→				Hash: entry.Hash,
806→			}
807→		}
808→	}
809→	return nil
810→}
