 984→// BuildTreeFromEntries builds a proper git tree structure from flattened file entries.
 985→// Exported for use by strategy package (push_common.go, session_test.go)
 986→func BuildTreeFromEntries(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
 987→	// Build a tree structure
 988→	root := &treeNode{
 989→		entries: make(map[string]*treeNode),
 990→		files:   []object.TreeEntry{},
 991→	}
 992→
 993→	// Insert all entries into the tree structure
 994→	for fullPath, entry := range entries {
 995→		parts := strings.Split(fullPath, "/")
 996→		insertIntoTree(root, parts, entry)
 997→	}
 998→
 999→	// Recursively build tree objects from bottom up
1000→	return buildTreeObject(repo, root)
1001→}
