1003→// insertIntoTree inserts a file entry into the tree structure.
1004→func insertIntoTree(node *treeNode, pathParts []string, entry object.TreeEntry) {
1005→	if len(pathParts) == 1 {
1006→		// This is a file in the current directory
1007→		node.files = append(node.files, object.TreeEntry{
1008→			Name: pathParts[0],
1009→			Mode: entry.Mode,
1010→			Hash: entry.Hash,
1011→		})
1012→		return
1013→	}
1014→
1015→	// This is in a subdirectory
1016→	dirName := pathParts[0]
1017→	if node.entries[dirName] == nil {
1018→		node.entries[dirName] = &treeNode{
1019→			entries: make(map[string]*treeNode),
1020→			files:   []object.TreeEntry{},
1021→		}
1022→	}
1023→	insertIntoTree(node.entries[dirName], pathParts[1:], entry)
1024→}
1025→
1026→// buildTreeObject recursively builds tree objects from a treeNode.
1027→func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
1028→	var treeEntries []object.TreeEntry
1029→
1030→	// Add files
1031→	treeEntries = append(treeEntries, node.files...)
1032→
1033→	// Recursively build subtrees
1034→	for name, subnode := range node.entries {
1035→		subHash, err := buildTreeObject(repo, subnode)
1036→		if err != nil {
1037→			return plumbing.ZeroHash, err
1038→		}
1039→		treeEntries = append(treeEntries, object.TreeEntry{
1040→			Name: name,
1041→			Mode: filemode.Dir,
1042→			Hash: subHash,
1043→		})
1044→	}
1045→
1046→	// Sort entries (git requires sorted entries)
1047→	sortTreeEntries(treeEntries)
1048→
1049→	// Create tree object
1050→	tree := &object.Tree{Entries: treeEntries}
1051→
1052→	obj := repo.Storer.NewEncodedObject()
1053→	if err := tree.Encode(obj); err != nil {
1054→		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
1055→	}
1056→
1057→	hash, err := repo.Storer.SetEncodedObject(obj)
1058→	if err != nil {
1059→		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
1060→	}
1061→
1062→	return hash, nil
1063→}

