		t.Chdir(tmpDir)

		if IsInsideWorktree(context.Background()) {
			t.Error("IsInsideWorktree(context.Background()) should return false in non-repo")
		}
	})
}

func TestGetMainRepoRoot(t *testing.T) {
	t.Run("main repo", func(t *testing.T) {
