118→// flattenCheckpointEntries reads only the entries under a specific checkpoint path
119→// from the sessions branch tree. This is O(files in checkpoint) instead of O(all checkpoints).
120→// Returns an empty map if the checkpoint doesn't exist yet.
121→func (s *GitStore) flattenCheckpointEntries(rootTreeHash plumbing.Hash, checkpointPath string) (map[string]object.TreeEntry, error) {
122→	entries := make(map[string]object.TreeEntry)
123→	if rootTreeHash == plumbing.ZeroHash {
124→		return entries, nil
125→	}
126→
127→	rootTree, err := s.repo.TreeObject(rootTreeHash)
128→	if err != nil {
129→		if errors.Is(err, plumbing.ErrObjectNotFound) {
130→			return entries, nil // Tree doesn't exist yet
131→		}
132→		return nil, fmt.Errorf("failed to read root tree %s: %w", rootTreeHash, err)
133→	}
134→
135→	subtree, err := rootTree.Tree(checkpointPath)
136→	if err != nil {
137→		return entries, nil //nolint:nilerr // Checkpoint doesn't exist yet
138→	}
139→
140→	// Flatten just this subtree with the full path prefix
141→	if err := FlattenTree(s.repo, subtree, checkpointPath, entries); err != nil {
142→		return nil, err
143→	}
144→	return entries, nil
145→}
