187→// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
188→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
189→	incData, err := redact.JSONLBytes(opts.IncrementalData)
