218→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
219→func (s *GitStore) writeFinalTaskCheckpoint(ctx context.Context, opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
220→	checkpoint := taskCheckpointData{
221→		SessionID:      opts.SessionID,
222→		ToolUseID:      opts.ToolUseID,
223→		CheckpointUUID: opts.CheckpointUUID,
224→		AgentID:        opts.AgentID,
225→	}
226→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
227→	if err != nil {
228→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
229→	}
230→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
231→	if err != nil {
232→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
233→	}
234→
235→	checkpointFile := taskPath + "checkpoint.json"
236→	entries[checkpointFile] = object.TreeEntry{
237→		Name: checkpointFile,
238→		Mode: filemode.Regular,
239→		Hash: blobHash,
240→	}
241→
242→	// Write subagent transcript if available
243→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
244→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
245→		if readErr == nil {
246→			// Try JSONL-aware redaction first; fall back to plain string redaction
247→			// if the content is not valid JSONL (avoids silently dropping the transcript).
248→			redacted, jsonlErr := redact.JSONLBytes(agentContent)
249→			if jsonlErr != nil {
250→				logging.Warn(ctx, "subagent transcript is not valid JSONL, falling back to plain redaction",
251→					slog.String("path", opts.SubagentTranscriptPath),
252→					slog.String("error", jsonlErr.Error()),
253→				)
254→				redacted = redact.Bytes(agentContent)
255→			}
256→			agentContent = redacted
257→
258→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
259→			if agentBlobErr == nil {
260→				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
261→				entries[agentPath] = object.TreeEntry{
262→					Name: agentPath,
263→					Mode: filemode.Regular,
264→					Hash: agentBlobHash,
265→				}
266→			}
267→		}
268→	}
269→
270→	// Return task path without trailing slash
271→	return taskPath[:len(taskPath)-1], nil
272→}
