331→// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
332→// Returns the absolute file paths from the git tree root for the sessions map.
333→func (s *GitStore) writeSessionToSubdirectory(ctx context.Context, opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
334→	filePaths := SessionFilePaths{}
335→
336→	// Clear any existing entries at this path so stale files from a previous
337→	// write (e.g. prompt.txt, context.md) don't persist on overwrite.
338→	for key := range entries {
339→		if strings.HasPrefix(key, sessionPath) {
340→			delete(entries, key)
341→		}
342→	}
343→
344→	// Write transcript
345→	if err := s.writeTranscript(ctx, opts, sessionPath, entries); err != nil {
346→		return filePaths, err
347→	}
348→	filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
349→	filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
350→
351→	// Write prompts
352→	if len(opts.Prompts) > 0 {
353→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
354→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
355→		if err != nil {
356→			return filePaths, err
357→		}
358→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
359→			Name: sessionPath + paths.PromptFileName,
360→			Mode: filemode.Regular,
361→			Hash: blobHash,
362→		}
363→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
364→	}
365→
366→	// Write context
367→	if len(opts.Context) > 0 {
368→		blobHash, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
369→		if err != nil {
370→			return filePaths, err
371→		}
372→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
373→			Name: sessionPath + paths.ContextFileName,
374→			Mode: filemode.Regular,
375→			Hash: blobHash,
376→		}
377→		filePaths.Context = "/" + sessionPath + paths.ContextFileName
378→	}
379→
380→	// Write session-level metadata.json (CommittedMetadata with all fields including initial_attribution)
381→	sessionMetadata := CommittedMetadata{
382→		CheckpointID:                opts.CheckpointID,
383→		SessionID:                   opts.SessionID,
384→		Strategy:                    opts.Strategy,
385→		CreatedAt:                   time.Now().UTC(),
386→		Branch:                      opts.Branch,
387→		CheckpointsCount:            opts.CheckpointsCount,
388→		FilesTouched:                opts.FilesTouched,
389→		Agent:                       opts.Agent,
390→		TurnID:                      opts.TurnID,
391→		IsTask:                      opts.IsTask,
392→		ToolUseID:                   opts.ToolUseID,
393→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
394→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
395→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
396→		TokenUsage:                  opts.TokenUsage,
397→		InitialAttribution:          opts.InitialAttribution,
398→		Summary:                     redactSummary(opts.Summary),
399→		CLIVersion:                  versioninfo.Version,
400→	}
401→
402→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
403→	if err != nil {
404→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
405→	}
406→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
407→	if err != nil {
408→		return filePaths, err
409→	}
410→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
411→		Name: sessionPath + paths.MetadataFileName,
412→		Mode: filemode.Regular,
413→		Hash: metadataHash,
414→	}
415→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
416→
417→	return filePaths, nil
418→}
