421→// sessions is the complete sessions array (already built by the caller).
422→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
423→	checkpointsCount, filesTouched, tokenUsage, err :=
424→		s.reaggregateFromEntries(basePath, len(sessions), entries)
425→	if err != nil {
426→		return fmt.Errorf("failed to aggregate session stats: %w", err)
427→	}
428→
429→	summary := CheckpointSummary{
430→		CheckpointID:     opts.CheckpointID,
431→		CLIVersion:       versioninfo.Version,
432→		Strategy:         opts.Strategy,
433→		Branch:           opts.Branch,
434→		CheckpointsCount: checkpointsCount,
435→		FilesTouched:     filesTouched,
436→		Sessions:         sessions,
437→		TokenUsage:       tokenUsage,
438→	}
439→
440→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
441→	if err != nil {
442→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
443→	}
444→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
445→	if err != nil {
446→		return err
447→	}
448→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
449→		Name: basePath + paths.MetadataFileName,
450→		Mode: filemode.Regular,
451→		Hash: metadataHash,
452→	}
453→	return nil
454→}
