456→// findSessionIndex returns the index of an existing session with the given ID,
457→// or the next available index if not found. This prevents duplicate session entries.
458→func (s *GitStore) findSessionIndex(ctx context.Context, basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
459→	if existingSummary == nil {
460→		return 0
461→	}
462→	for i := range len(existingSummary.Sessions) {
463→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
464→		if entry, exists := entries[path]; exists {
465→			meta, err := s.readMetadataFromBlob(entry.Hash)
466→			if err != nil {
467→				logging.Warn(ctx, "failed to read session metadata during dedup check",
468→					slog.Int("session_index", i),
469→					slog.String("session_id", sessionID),
470→					slog.String("error", err.Error()),
471→				)
472→				continue
473→			}
474→			if meta.SessionID == sessionID {
475→				return i
476→			}
477→		}
478→	}
479→	return len(existingSummary.Sessions)
480→}
