482→// reaggregateFromEntries reads all session metadata from the entries map and
483→// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
484→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
485→	var totalCount int
486→	var allFiles []string
487→	var totalTokens *agent.TokenUsage
488→
489→	for i := range sessionCount {
490→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
491→		entry, exists := entries[path]
492→		if !exists {
493→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
494→		}
495→		meta, err := s.readMetadataFromBlob(entry.Hash)
496→		if err != nil {
497→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
498→		}
499→		totalCount += meta.CheckpointsCount
500→		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)

600→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
601→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
602→	if err != nil {
603→		return err
604→	}
605→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
606→		Name: basePath + paths.ContentHashFileName,
607→		Mode: filemode.Regular,
608→		Hash: hashBlob,
609→	}
