613→// mergeFilesTouched combines two file lists, removing duplicates.
614→func mergeFilesTouched(existing, additional []string) []string {
615→	seen := make(map[string]bool)
616→	var result []string
617→
618→	for _, f := range existing {
619→		if !seen[f] {
620→			seen[f] = true
621→			result = append(result, f)
622→		}
623→	}
624→	for _, f := range additional {
625→		if !seen[f] {
626→			seen[f] = true
627→			result = append(result, f)
628→		}
629→	}
630→
631→	sort.Strings(result)
632→	return result
633→}
