635→// redactSummary returns a copy of the summary with text fields redacted.
636→// Structural fields (Path, Line, EndLine) are preserved.
637→// NOTE: When adding new text fields to Summary, LearningsSummary, or CodeLearning,
638→// update this function to include them in redaction.
639→func redactSummary(s *Summary) *Summary {
640→	if s == nil {
641→		return nil
642→	}
643→	return &Summary{
644→		Intent:    redact.String(s.Intent),
645→		Outcome:   redact.String(s.Outcome),
646→		Friction:  redactStringSlice(s.Friction),
647→		OpenItems: redactStringSlice(s.OpenItems),
648→		Learnings: LearningsSummary{
649→			Repo:     redactStringSlice(s.Learnings.Repo),
650→			Workflow: redactStringSlice(s.Learnings.Workflow),
651→			Code:     redactCodeLearnings(s.Learnings.Code),
652→		},
653→	}
654→}
