656→// redactStringSlice applies redact.String to each element.
657→func redactStringSlice(ss []string) []string {
658→	if ss == nil {
659→		return nil
660→	}
661→	out := make([]string, len(ss))
662→	for i, s := range ss {
663→		out[i] = redact.String(s)
664→	}
665→	return out
666→}
