668→// redactCodeLearnings redacts only the Finding field, preserving Path/Line/EndLine.
669→func redactCodeLearnings(cls []CodeLearning) []CodeLearning {
670→	if cls == nil {
671→		return nil
672→	}
673→	out := make([]CodeLearning, len(cls))
674→	for i, cl := range cls {
675→		out[i] = CodeLearning{
676→			Path:    cl.Path,
677→			Line:    cl.Line,
678→			EndLine: cl.EndLine,
679→			Finding: redact.String(cl.Finding),
680→		}
681→	}
682→	return out
683→}
