690→// buildCommitMessage constructs the commit message with proper trailers.
691→// The commit subject is always "Checkpoint: <id>" for consistency.
692→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
693→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
694→	var commitMsg strings.Builder
695→
696→	// Subject line is always the checkpoint ID for consistent formatting
697→	fmt.Fprintf(&commitMsg, "Checkpoint: %s\n\n", opts.CheckpointID)
698→
699→	// Include custom description in body if provided (e.g., task checkpoint details)
700→	if opts.CommitSubject != "" {
701→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
702→	}
703→	fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.SessionTrailerKey, opts.SessionID)
704→	fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy)
705→	if opts.Agent != "" {
706→		fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.AgentTrailerKey, opts.Agent)
707→	}
708→	if opts.EphemeralBranch != "" {
709→		fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch)
710→	}
711→	if taskMetadataPath != "" {
712→		fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath)
713→	}
714→
715→	return commitMsg.String()
716→}
