736→// ReadCommitted reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
737→// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
738→// Use ReadSessionContent to read actual transcript/prompts/context.
739→// Returns nil, nil if the checkpoint doesn't exist.
740→//
741→// The storage format uses numbered subdirectories for each session (0-based):
742→//
743→//	<checkpoint-id>/
744→//	├── metadata.json      # CheckpointSummary with sessions map
745→//	├── 0/                 # First session
746→//	│   ├── metadata.json  # Session-specific metadata
747→//	│   └── full.jsonl     # Transcript
748→//	├── 1/                 # Second session
749→//	└── ...
750→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
751→	_ = ctx // Reserved for future use
752→
753→	tree, err := s.getSessionsBranchTree()
754→	if err != nil {
755→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
756→	}
757→
758→	checkpointPath := checkpointID.Path()
759→	checkpointTree, err := tree.Tree(checkpointPath)
760→	if err != nil {
761→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
762→	}
763→
764→	// Read root metadata.json as CheckpointSummary
765→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
766→	if err != nil {
767→		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
768→	}
769→
770→	content, err := metadataFile.Contents()
771→	if err != nil {
