783→// ReadSessionContent reads the actual content for a specific session within a checkpoint.
784→// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
785→// Returns the session's metadata, transcript, prompts, and context.
786→// Returns an error if the checkpoint or session doesn't exist.
787→func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
788→	_ = ctx // Reserved for future use
789→
790→	tree, err := s.getSessionsBranchTree()
791→	if err != nil {
792→		return nil, ErrCheckpointNotFound
793→	}
794→
795→	checkpointPath := checkpointID.Path()
796→	checkpointTree, err := tree.Tree(checkpointPath)
797→	if err != nil {
798→		return nil, ErrCheckpointNotFound
799→	}
800→
801→	// Get the session subdirectory
802→	sessionDir := strconv.Itoa(sessionIndex)
803→	sessionTree, err := checkpointTree.Tree(sessionDir)
804→	if err != nil {
805→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
806→	}
807→
808→	result := &SessionContent{}
809→
810→	// Read session-specific metadata
811→	var agentType agent.AgentType
812→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
813→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
814→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
815→				agentType = result.Metadata.Agent
816→			}
817→		}
818→	}
819→
820→	// Read transcript
821→	if transcript, transcriptErr := readTranscriptFromTree(ctx, sessionTree, agentType); transcriptErr == nil && transcript != nil {
822→		result.Transcript = transcript
823→	}
824→
825→	// Read prompts
826→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
827→		if content, contentErr := file.Contents(); contentErr == nil {
828→			result.Prompts = content
829→		}
830→	}
831→
832→	// Read context
833→	if file, fileErr := sessionTree.File(paths.ContextFileName); fileErr == nil {
834→		if content, contentErr := file.Contents(); contentErr == nil {
835→			result.Context = content
836→		}
837→	}
838→
839→	return result, nil
840→}
