860→// ReadSessionContentByID reads a session's content by its session ID.
861→// This is useful when you have the session ID but don't know its index within the checkpoint.
862→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
863→// Returns an error if no session with the given ID exists in the checkpoint.
864→func (s *GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
865→	summary, err := s.ReadCommitted(ctx, checkpointID)
866→	if err != nil {
867→		return nil, err
868→	}
869→	if summary == nil {
870→		return nil, ErrCheckpointNotFound
871→	}
872→
873→	// Iterate through sessions to find the one with matching session ID
874→	for i := range len(summary.Sessions) {
875→		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
876→		if readErr != nil {
877→			continue
878→		}
879→		if content != nil && content.Metadata.SessionID == sessionID {
880→			return content, nil
881→		}
882→	}
883→
884→	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
885→}
