887→// ListCommitted lists all committed checkpoints from the entire/checkpoints/v1 branch.
888→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
889→//
890→
891→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
892→	_ = ctx // Reserved for future use
893→
894→	tree, err := s.getSessionsBranchTree()
895→	if err != nil {
896→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
897→	}
898→
899→	var checkpoints []CommittedInfo

 900→
 901→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
 902→	for _, bucketEntry := range tree.Entries {
 903→		if bucketEntry.Mode != filemode.Dir {
 904→			continue
 905→		}
 906→		// Bucket should be 2 hex chars
 907→		if len(bucketEntry.Name) != 2 {
 908→			continue
 909→		}
 910→
 911→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
 912→		if treeErr != nil {
 913→			continue
 914→		}
 915→
 916→		// Each entry in the bucket is the remaining part of the checkpoint ID
 917→		for _, checkpointEntry := range bucketTree.Entries {
 918→			if checkpointEntry.Mode != filemode.Dir {
 919→				continue
 920→			}
 921→
 922→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
 923→			if cpTreeErr != nil {
 924→				continue
 925→			}
 926→
 927→			// Reconstruct checkpoint ID: <bucket><remaining>
 928→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
 929→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
 930→			if cpIDErr != nil {
 931→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
 932→				continue
 933→			}
 934→
 935→			info := CommittedInfo{
 936→				CheckpointID: checkpointID,
 937→			}
 938→
 939→			// Get details from root metadata file (CheckpointSummary format)
 940→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
 941→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
 942→					var summary CheckpointSummary
 943→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
 944→						info.CheckpointsCount = summary.CheckpointsCount
 945→						info.FilesTouched = summary.FilesTouched
 946→						info.SessionCount = len(summary.Sessions)
 947→
 948→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
 949→						if len(summary.Sessions) > 0 {
 950→							latestIndex := len(summary.Sessions) - 1
 951→							latestDir := strconv.Itoa(latestIndex)
 952→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
 953→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
 954→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
 955→										var sessionMetadata CommittedMetadata
 956→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
 957→											info.Agent = sessionMetadata.Agent
 958→											info.SessionID = sessionMetadata.SessionID
 959→											info.CreatedAt = sessionMetadata.CreatedAt
 960→										}
 961→									}
 962→								}
 963→							}
 964→						}
 965→					}
 966→				}
 967→			}
 968→
 969→			checkpoints = append(checkpoints, info)
 970→		}
 971→	}
 972→
 973→	// Sort by time (most recent first)
 974→	sort.Slice(checkpoints, func(i, j int) bool {
 975→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
 976→	})
 977→
 978→	return checkpoints, nil
 979→}
