1026→// UpdateSummary updates the summary field in the latest session's metadata.
1027→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1028→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
1029→	_ = ctx // Reserved for future use
1030→
1031→	// Ensure sessions branch exists
1032→	if err := s.ensureSessionsBranch(); err != nil {
1033→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
1034→	}
1035→
1036→	// Get branch ref and root tree hash (O(1), no flatten)
1037→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
1038→	if err != nil {
1039→		return err
1040→	}
1041→
1042→	// Flatten only the checkpoint subtree
1043→	basePath := checkpointID.Path() + "/"
1044→	checkpointPath := checkpointID.Path()
1045→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1046→	if err != nil {
1047→		return err
1048→	}
1049→
1050→	// Read root CheckpointSummary to find the latest session
1051→	rootMetadataPath := basePath + paths.MetadataFileName
1052→	entry, exists := entries[rootMetadataPath]
1053→	if !exists {
1054→		return ErrCheckpointNotFound
1055→	}
1056→
1057→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
1058→	if err != nil {
1059→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
1060→	}
1061→
1062→	// Find the latest session's metadata path (0-based indexing)
1063→	latestIndex := len(checkpointSummary.Sessions) - 1
1064→	sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
1065→	sessionEntry, exists := entries[sessionMetadataPath]
1066→	if !exists {
1067→		return fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
1068→	}
1069→
1070→	// Read and update session metadata
1071→	existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
1072→	if err != nil {
1073→		return fmt.Errorf("failed to read session metadata: %w", err)
1074→	}
1075→
1076→	// Update the summary
1077→	existingMetadata.Summary = redactSummary(summary)
1078→
1079→	// Write updated session metadata
1080→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
1081→	if err != nil {
1082→		return fmt.Errorf("failed to marshal metadata: %w", err)
1083→	}
1084→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
1085→	if err != nil {
1086→		return fmt.Errorf("failed to create metadata blob: %w", err)
1087→	}
1088→	entries[sessionMetadataPath] = object.TreeEntry{
1089→		Name: sessionMetadataPath,
1090→		Mode: filemode.Regular,
1091→		Hash: metadataHash,
1092→	}
1093→
1094→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
1095→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, checkpointID, basePath, entries)
1096→	if err != nil {
1097→		return err
1098→	}
1099→
1100→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1101→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
1102→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, authorName, authorEmail)
1103→	if err != nil {
1104→		return err
1105→	}
1106→
1107→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1108→	newRef := plumbing.NewHashReference(refName, newCommitHash)
1109→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1110→		return fmt.Errorf("failed to set branch reference: %w", err)
1111→	}
1112→
1113→	return nil
1114→}
