1116→// UpdateCommitted replaces the transcript, prompts, and context for an existing
1117→// committed checkpoint. Uses replace semantics: the full session transcript is
1118→// written, replacing whatever was stored at initial condensation time.
1119→//
1120→// This is called at stop time to finalize all checkpoints from the current turn
1121→// with the complete session transcript (from prompt to stop event).
1122→//
1123→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1124→func (s *GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
1125→	if opts.CheckpointID.IsEmpty() {
1126→		return errors.New("invalid update options: checkpoint ID is required")
1127→	}
1128→
1129→	// Ensure sessions branch exists
1130→	if err := s.ensureSessionsBranch(); err != nil {
1131→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
1132→	}
1133→
1134→	// Get branch ref and root tree hash (O(1), no flatten)
1135→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
1136→	if err != nil {
1137→		return err
1138→	}
1139→
1140→	// Flatten only the checkpoint subtree
1141→	basePath := opts.CheckpointID.Path() + "/"
1142→	checkpointPath := opts.CheckpointID.Path()
1143→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1144→	if err != nil {
1145→		return err
1146→	}
1147→
1148→	// Read root CheckpointSummary to find the session slot
1149→	rootMetadataPath := basePath + paths.MetadataFileName
1150→	entry, exists := entries[rootMetadataPath]
1151→	if !exists {
1152→		return ErrCheckpointNotFound
1153→	}
1154→
1155→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
1156→	if err != nil {
1157→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
1158→	}
1159→	if len(checkpointSummary.Sessions) == 0 {
1160→		return ErrCheckpointNotFound
1161→	}
1162→
1163→	// Find session index matching opts.SessionID
1164→	sessionIndex := -1
1165→	for i := range len(checkpointSummary.Sessions) {
1166→		metaPath := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
1167→		if metaEntry, metaExists := entries[metaPath]; metaExists {
1168→			meta, metaErr := s.readMetadataFromBlob(metaEntry.Hash)
1169→			if metaErr == nil && meta.SessionID == opts.SessionID {
1170→				sessionIndex = i
1171→				break
1172→			}
1173→		}
1174→	}
1175→	if sessionIndex == -1 {
1176→		// Fall back to latest session; log so mismatches are diagnosable.
1177→		sessionIndex = len(checkpointSummary.Sessions) - 1
1178→		logging.Debug(ctx, "UpdateCommitted: session ID not found, falling back to latest",
1179→			slog.String("session_id", opts.SessionID),
1180→			slog.String("checkpoint_id", string(opts.CheckpointID)),
1181→			slog.Int("fallback_index", sessionIndex),
1182→		)
1183→	}
1184→
1185→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
1186→
1187→	// Replace transcript (full replace, not append)
1188→	// Apply redaction as safety net (caller should redact, but we ensure it here)
1189→	if len(opts.Transcript) > 0 {
1190→		transcript, err := redact.JSONLBytes(opts.Transcript)
1191→		if err != nil {
1192→			return fmt.Errorf("failed to redact transcript secrets: %w", err)
1193→		}
1194→		if err := s.replaceTranscript(ctx, transcript, opts.Agent, sessionPath, entries); err != nil {
1195→			return fmt.Errorf("failed to replace transcript: %w", err)
1196→		}
1197→	}
1198→
1199→	// Replace prompts (apply redaction as safety net)

1200→	if len(opts.Prompts) > 0 {
1201→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
1202→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
1203→		if err != nil {
1204→			return fmt.Errorf("failed to create prompt blob: %w", err)
1205→		}
1206→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
1207→			Name: sessionPath + paths.PromptFileName,
1208→			Mode: filemode.Regular,
1209→			Hash: blobHash,
1210→		}
1211→	}
1212→
1213→	// Replace context (apply redaction as safety net)
1214→	if len(opts.Context) > 0 {
1215→		contextBlob, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
1216→		if err != nil {
1217→			return fmt.Errorf("failed to create context blob: %w", err)
1218→		}
1219→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
1220→			Name: sessionPath + paths.ContextFileName,
1221→			Mode: filemode.Regular,
1222→			Hash: contextBlob,
1223→		}
1224→	}
1225→
1226→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
1227→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
1228→	if err != nil {
1229→		return err
1230→	}
1231→
1232→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1233→	commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
1234→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, authorName, authorEmail)
1235→	if err != nil {
1236→		return err
1237→	}
1238→
1239→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1240→	newRef := plumbing.NewHashReference(refName, newCommitHash)
1241→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1242→		return fmt.Errorf("failed to set branch reference: %w", err)
1243→	}
1244→
1245→	return nil
1246→}
