1248→// replaceTranscript writes the full transcript content, replacing any existing transcript.
1249→// Also removes any chunk files from a previous write and updates the content hash.
1250→func (s *GitStore) replaceTranscript(ctx context.Context, transcript []byte, agentType agent.AgentType, sessionPath string, entries map[string]object.TreeEntry) error {
1251→	// Remove existing transcript files (base + any chunks)
1252→	transcriptBase := sessionPath + paths.TranscriptFileName
1253→	for key := range entries {
1254→		if key == transcriptBase || strings.HasPrefix(key, transcriptBase+".") {
1255→			delete(entries, key)
1256→		}
1257→	}
1258→
1259→	// Chunk the transcript (matches writeTranscript behavior)
1260→	chunks, err := agent.ChunkTranscript(ctx, transcript, agentType)
1261→	if err != nil {
1262→		return fmt.Errorf("failed to chunk transcript: %w", err)
1263→	}
1264→
1265→	// Write chunk files
1266→	for i, chunk := range chunks {
1267→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
1268→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
1269→		if err != nil {
1270→			return fmt.Errorf("failed to create transcript blob: %w", err)
1271→		}
1272→		entries[chunkPath] = object.TreeEntry{
1273→			Name: chunkPath,
1274→			Mode: filemode.Regular,
1275→			Hash: blobHash,
1276→		}
1277→	}
1278→
1279→	// Update content hash
1280→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
1281→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
1282→	if err != nil {
1283→		return fmt.Errorf("failed to create content hash blob: %w", err)
1284→	}
1285→	hashPath := sessionPath + paths.ContentHashFileName
1286→	entries[hashPath] = object.TreeEntry{
1287→		Name: hashPath,
1288→		Mode: filemode.Regular,
1289→		Hash: hashBlob,
1290→	}
1291→
1292→	return nil
1293→}
