1295→// ensureSessionsBranch ensures the entire/checkpoints/v1 branch exists.
1296→func (s *GitStore) ensureSessionsBranch() error {
1297→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1298→	_, err := s.repo.Reference(refName, true)
1299→	if err == nil {
1300→		return nil // Branch exists
1301→	}
1302→
1303→	// Create orphan branch with empty tree
1304→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
1305→	if err != nil {
1306→		return err
1307→	}
1308→
1309→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1310→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
1311→	if err != nil {
1312→		return err
1313→	}
1314→
1315→	newRef := plumbing.NewHashReference(refName, commitHash)
1316→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1317→		return fmt.Errorf("failed to set branch reference: %w", err)
1318→	}
1319→	return nil
1320→}
1321→
1322→// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
1323→// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
