1349→// CreateBlobFromContent creates a blob object from in-memory content.
1350→// Exported for use by strategy package (session_test.go)
1351→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1352→	obj := repo.Storer.NewEncodedObject()
1353→	obj.SetType(plumbing.BlobObject)
1354→	obj.SetSize(int64(len(content)))
1355→
1356→	writer, err := obj.Writer()
1357→	if err != nil {
1358→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1359→	}
1360→
1361→	_, err = writer.Write(content)
1362→	if err != nil {
1363→		_ = writer.Close()
1364→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1365→	}
1366→	if err := writer.Close(); err != nil {
1367→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1368→	}
1369→
1370→	hash, err := repo.Storer.SetEncodedObject(obj)
1371→	if err != nil {
1372→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1373→	}
1374→	return hash, nil
1375→}
