1377→// copyMetadataDir copies all files from a directory to the checkpoint path.
1378→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
1379→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
1380→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
1381→		if err != nil {
1382→			return err
1383→		}
1384→
1385→		// Skip symlinks to prevent reading files outside the metadata directory.
1386→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
1387→		// then be captured in the checkpoint and stored in git history.
1388→		// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
1389→		// reports ModeSymlink. We use os.Lstat to check the entry itself.
1390→		// This check MUST come before IsDir() because Walk follows symlinked
1391→		// directories and would recurse into them otherwise.
1392→		linfo, lstatErr := os.Lstat(path)
1393→		if lstatErr != nil {
1394→			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
1395→		}
1396→		if linfo.Mode()&os.ModeSymlink != 0 {
1397→			if info.IsDir() {
1398→				return filepath.SkipDir
1399→			}
1400→			return nil
1401→		}
1402→
1403→		if info.IsDir() {
1404→			return nil
1405→		}
1406→
1407→		// Get relative path within metadata dir
1408→		relPath, err := filepath.Rel(metadataDir, path)
1409→		if err != nil {
1410→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
1411→		}
1412→
1413→		// Prevent path traversal via symlinks pointing outside the metadata dir
1414→		if strings.HasPrefix(relPath, "..") {
1415→			return fmt.Errorf("path traversal detected: %s", relPath)
1416→		}
1417→
1418→		// Create blob from file with secrets redaction
1419→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
1420→		if err != nil {
1421→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
1422→		}
1423→
1424→		// Store at checkpoint path (use forward slashes for git tree compatibility on Windows)
1425→		fullPath := basePath + filepath.ToSlash(relPath)
1426→		entries[fullPath] = object.TreeEntry{
1427→			Name: fullPath,
1428→			Mode: mode,
1429→			Hash: blobHash,
1430→		}
1431→
1432→		return nil
1433→	})
1434→	if err != nil {
1435→		return fmt.Errorf("failed to walk metadata directory: %w", err)
1436→	}
