1440→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1441→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1442→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1443→	info, err := os.Stat(filePath)
1444→	if err != nil {
1445→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1446→	}
1447→
1448→	mode := filemode.Regular
1449→	if info.Mode()&0o111 != 0 {
1450→		mode = filemode.Executable
1451→	}
1452→
1453→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1454→	if err != nil {
1455→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1456→	}
1457→
1458→	// Skip redaction for binary files — they can't contain text secrets and
1459→	// running string replacement on them would corrupt the data.
1460→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1461→	if binErr != nil || isBin {
1462→		hash, err := CreateBlobFromContent(repo, content)
1463→		if err != nil {
1464→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1465→		}
1466→		return hash, mode, nil
1467→	}
1468→
1469→	if strings.HasSuffix(treePath, ".jsonl") {
1470→		redacted, jsonlErr := redact.JSONLBytes(content)
1471→		if jsonlErr != nil {
1472→			redacted = redact.Bytes(content)
1473→		}
1474→		content = redacted
1475→	} else {
1476→		content = redact.Bytes(content)
1477→	}
1478→
1479→	hash, err := CreateBlobFromContent(repo, content)
1480→	if err != nil {
1481→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1482→	}
1483→	return hash, mode, nil
1484→}
