288→// EnsureMetadataBranch creates or updates the local entire/checkpoints/v1 branch.
289→// If the remote-tracking branch (origin/entire/checkpoints/v1) exists and the local
290→// branch is missing or empty, creates/updates the local branch from it.
291→// Otherwise creates an empty orphan.
292→func EnsureMetadataBranch(repo *git.Repository) error {
293→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
294→
295→	// Check if remote-tracking branch exists (e.g., after clone/fetch)
296→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
297→	remoteRef, remoteErr := repo.Reference(remoteRefName, true)
298→	if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
299→		return fmt.Errorf("failed to check remote metadata branch: %w", remoteErr)
300→	}
301→
302→	// Check if local branch already exists
303→	localRef, err := repo.Reference(refName, true)
304→	if err == nil {
305→		if remoteErr == nil && localRef.Hash() != remoteRef.Hash() {
306→			// Local and remote exist but differ — determine relationship
307→			isEmpty, checkErr := isEmptyMetadataBranch(repo, localRef)
308→			if checkErr == nil && isEmpty {
309→				// Empty orphan — just point to remote
310→				ref := plumbing.NewHashReference(refName, remoteRef.Hash())
311→				if setErr := repo.Storer.SetReference(ref); setErr != nil {
312→					return fmt.Errorf("failed to update metadata branch from remote: %w", setErr)
313→				}
314→				fmt.Fprintf(os.Stderr, "✓ Updated local branch '%s' from origin\n", paths.MetadataBranchName)
315→			} else if checkErr == nil {
316→				// Local has real data — check ancestry
317→				if err := syncMetadataBranch(repo, refName, localRef, remoteRef); err != nil {
318→					return err
319→				}
320→			}
321→		}
322→		return nil
323→	}
324→	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
325→		return fmt.Errorf("failed to check metadata branch: %w", err)
326→	}
327→
328→	// Local branch doesn't exist — create from remote if available
329→	if remoteErr == nil {
330→		ref := plumbing.NewHashReference(refName, remoteRef.Hash())
331→		if err := repo.Storer.SetReference(ref); err != nil {
332→			return fmt.Errorf("failed to create metadata branch from remote: %w", err)
333→		}
334→		fmt.Fprintf(os.Stderr, "✓ Created local branch '%s' from origin\n", paths.MetadataBranchName)
335→		return nil
336→	}
337→
338→	// No local or remote branch — create empty orphan
339→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
340→	obj := repo.Storer.NewEncodedObject()
341→	if err := emptyTree.Encode(obj); err != nil {
342→		return fmt.Errorf("failed to encode empty tree: %w", err)
343→	}
344→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
345→	if err != nil {
346→		return fmt.Errorf("failed to store empty tree: %w", err)
347→	}
348→
349→	// Create orphan commit (no parent)
350→	now := time.Now()
351→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
352→	sig := object.Signature{
353→		Name:  authorName,
354→		Email: authorEmail,
355→		When:  now,
356→	}
357→
358→	commit := &object.Commit{
359→		TreeHash:  emptyTreeHash,
360→		Author:    sig,
361→		Committer: sig,
362→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata.\n",
363→	}
364→	// Note: No ParentHashes - this is an orphan commit
365→
366→	commitObj := repo.Storer.NewEncodedObject()
367→	if err := commit.Encode(commitObj); err != nil {
368→		return fmt.Errorf("failed to encode orphan commit: %w", err)
369→	}
370→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
371→	if err != nil {
372→		return fmt.Errorf("failed to store orphan commit: %w", err)
373→	}
374→
375→	// Create branch reference
376→	ref := plumbing.NewHashReference(refName, commitHash)
377→	if err := repo.Storer.SetReference(ref); err != nil {
378→		return fmt.Errorf("failed to create metadata branch: %w", err)
379→	}
380→
381→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
382→	return nil
383→}
