490→// readCheckpointMetadata reads metadata.json from a checkpoint path on entire/checkpoints/v1.
491→// With the new format, root metadata.json is a CheckpointSummary with Agents array.
492→// This function reads the summary and extracts relevant fields into CheckpointInfo,
493→// also reading session-level metadata for IsTask/ToolUseID fields.
494→func ReadCheckpointMetadata(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
495→	metadataPath := checkpointPath + "/metadata.json"
496→	file, err := tree.File(metadataPath)
497→	if err != nil {
498→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
499→	}
500→
501→	content, err := file.Contents()
502→	if err != nil {
503→		return nil, fmt.Errorf("failed to read metadata: %w", err)
504→	}
505→
506→	// Try to parse as CheckpointSummary first (new format)
507→	var summary checkpoint.CheckpointSummary
508→	if err := json.Unmarshal([]byte(content), &summary); err == nil {
509→		// If we have sessions array, this is the new format
510→		if len(summary.Sessions) > 0 {
511→			info := &CheckpointInfo{
512→				CheckpointID:     summary.CheckpointID,
513→				CheckpointsCount: summary.CheckpointsCount,
514→				FilesTouched:     summary.FilesTouched,
515→				SessionCount:     len(summary.Sessions),
516→			}
517→
518→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
519→			var sessionIDs []string
520→			for i, sessionPaths := range summary.Sessions {
521→				if sessionPaths.Metadata != "" {
522→					// SessionFilePaths now contains absolute paths with leading "/"
523→					// Strip the leading "/" for tree.File() which expects paths without leading slash
524→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
525→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
526→						if sessionContent, err := sessionFile.Contents(); err == nil {
527→							var sessionMetadata checkpoint.CommittedMetadata
528→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
529→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
530→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
531→								if i == 0 {
532→									info.Agent = sessionMetadata.Agent
533→									info.SessionID = sessionMetadata.SessionID
534→									info.CreatedAt = sessionMetadata.CreatedAt
535→									info.IsTask = sessionMetadata.IsTask
536→									info.ToolUseID = sessionMetadata.ToolUseID
537→								}
538→							}
539→						}
540→					}
541→				}
542→			}
543→			info.SessionIDs = sessionIDs
544→
545→			return info, nil
546→		}
547→	}

