398→// syncMetadataBranch handles the case where local and remote metadata branches both
399→// have real data but differ. Uses git merge-base to determine the relationship:
400→//   - remote is ancestor of local → already synced, nothing to do
401→//   - local is ancestor of remote → fast-forward local to remote
402→//   - no ancestor relationship → disconnected histories, merge trees
403→func syncMetadataBranch(repo *git.Repository, refName plumbing.ReferenceName, localRef, remoteRef *plumbing.Reference) error {
404→	localHash := localRef.Hash().String()
405→	remoteHash := remoteRef.Hash().String()
406→
407→	// Get repo path for git CLI commands
408→	wt, err := repo.Worktree()
409→	if err != nil {
410→		return fmt.Errorf("failed to get worktree: %w", err)
411→	}
412→	repoPath := wt.Filesystem.Root()
413→
414→	// Check if remote is ancestor of local (local is ahead — already synced)
415→	if isAncestorCLI(repoPath, remoteHash, localHash) {
416→		return nil
417→	}
418→
419→	// Check if local is ancestor of remote (local is behind — fast-forward)
420→	if isAncestorCLI(repoPath, localHash, remoteHash) {
421→		ref := plumbing.NewHashReference(refName, remoteRef.Hash())
422→		if err := repo.Storer.SetReference(ref); err != nil {
423→			return fmt.Errorf("failed to fast-forward metadata branch: %w", err)
424→		}
425→		fmt.Fprintf(os.Stderr, "✓ Updated local branch '%s' from origin\n", paths.MetadataBranchName)
426→		return nil
427→	}
428→
429→	// Disconnected or diverged — merge both trees
430→	localCommit, err := repo.CommitObject(localRef.Hash())
431→	if err != nil {
432→		return fmt.Errorf("failed to get local commit: %w", err)
433→	}
434→	localTree, err := localCommit.Tree()
435→	if err != nil {
436→		return fmt.Errorf("failed to get local tree: %w", err)
437→	}
438→
439→	remoteCommit, err := repo.CommitObject(remoteRef.Hash())
440→	if err != nil {
441→		return fmt.Errorf("failed to get remote commit: %w", err)
442→	}
443→	remoteTree, err := remoteCommit.Tree()
444→	if err != nil {
445→		return fmt.Errorf("failed to get remote tree: %w", err)
446→	}
447→
448→	// Flatten both trees and combine — checkpoint shards are unique, no conflicts
449→	entries := make(map[string]object.TreeEntry)
450→	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
451→		return fmt.Errorf("failed to flatten local tree: %w", err)
452→	}
453→	if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
454→		return fmt.Errorf("failed to flatten remote tree: %w", err)
455→	}
456→
457→	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
458→	if err != nil {
459→		return fmt.Errorf("failed to build merged tree: %w", err)
460→	}
461→
462→	mergeHash, err := createMergeCommitCommon(repo, mergedTreeHash,
463→		[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
464→		"Reconcile local and remote session metadata")
465→	if err != nil {
466→		return fmt.Errorf("failed to create merge commit: %w", err)
467→	}
468→
469→	ref := plumbing.NewHashReference(refName, mergeHash)
470→	if err := repo.Storer.SetReference(ref); err != nil {
471→		return fmt.Errorf("failed to update metadata branch: %w", err)
472→	}
473→
474→	fmt.Fprintf(os.Stderr, "✓ Reconciled local branch '%s' with origin\n", paths.MetadataBranchName)
475→	return nil
476→}
