478→// isAncestorCLI checks if commit A is an ancestor of commit B using git merge-base.
479→// Uses the CLI to avoid the depth limit of IsAncestorOf.
480→// Returns false if the commits are disconnected (no common ancestor).
481→// repoPath should be a path inside the git repository.
482→func isAncestorCLI(repoPath, commitA, commitB string) bool {
483→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
484→	defer cancel()
485→	cmd := exec.CommandContext(ctx, "git", "merge-base", "--is-ancestor", commitA, commitB)
486→	cmd.Dir = repoPath
487→	return cmd.Run() == nil
488→}
